      SUBROUTINE ERRSETCC     READ MAGNITUDES OF ERRORS FOR PHYSICAL PARAMETERSCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM26A.CIN'      INCLUDE 'ELM26B.CIN'CC----------------------------------------------------------------      TYPER = INT(DATA(I+1))      NPAR = INT(DATA(I+2))      DPAR = DATA(I+3)      IF (TYPER .GT. NELMCT) GO TO 1000      GO TO (1000,  20,  30,  40,  50,1000,  70,1000,1000,1000,     1        110,1000,1000,1000,1000,1000,1000, 180, 190, 200,     2       1000,1000,1000,1000, 250,1000,1000, 280, 280,1000,     3       1000,1000,1000, 340,1000,1000,1000,1000,1000,1000,     4       1000,1000, 430,1000,1000,1000,1000,1000), TYPERC   20 IF (NPAR .LT. 1 .OR. NPAR .GT. 4) GO TO 1000      PRAN2(NPAR) = DPAR      GO TO 1000C   30 IF (NPAR .NE. 1) GO TO 1000      PRAN3 = DPAR      GO TO 1000C   40 IF (NPAR .LT. 1 .OR. NPAR .GT. 15) GO TO 1000      PRAN4(NPAR) = DPAR      GO TO 1000C   50 IF (NPAR .LT. 1 .OR. NPAR .GT. 5) GO TO 1000      PRAN5(NPAR) = DPAR      GO TO 1000C   70 IF (NPAR .LT. 1 .OR. NPAR .GT. 6) GO TO 1000      PRAN7(NPAR) = DPAR      GO TO 1000C  110 IF (NPAR .LT. 1 .OR. NPAR .GT. 4) GO TO 1000      PRAN11(NPAR) = DPAR      GO TO 1000C  180 IF (NPAR .LT. 1 .OR. NPAR .GT. 4) GO TO 1000      PRAN18(NPAR) = DPAR      GO TO 1000C  190 IF (NPAR .LT. 1 .OR. NPAR .GT. 3) GO TO 1000      PRAN19(NPAR) = DPAR      GO TO 1000C  200 IF (NPAR .NE. 1) GO TO 1000      PRAN20 = DPAR      GO TO 1000C  250 IF (NPAR .LT. 1 .OR. NPAR .GT. 4) GO TO 1000      PRAN25(NPAR) = DPAR      GO TO 1000C  280 IF (NPAR .LT. 1 .OR. NPAR .GT. 23) GO TO 1000      PRAN28(NPAR) = DPAR      GO TO 1000C  340 IF (NPAR .LT. 1 .OR. NPAR .GT. 5) GO TO 1000      PRAN34(NPAR) = DPARC  430 IF (NPAR .LT. 1 .OR. NPAR .GT. 6) GO TO 1000      PRAN43(NPAR) = DPAR      GO TO 1000C 1000 RETURN      END